27	/** Adds the person, or another pool, to the pool with its share. Refuses a person not on the sheet, or one already in
28	 *  the pool; refuses a pool not on the sheet, one already a member of a pool, one that would contain itself through
29	 *  any chain, or one that would make a chain of pools more than three deep. */
30	public class ApplyPoolMember {
31	    private static final int MAX_DEPTH = 3;
32	
33	    public void apply(@Val ValidPoolMember request, @Val Pool pool, PersonRepository people, PoolRepository pools,
34	            PoolMemberRepository members, Out<PoolMember> memberOut, Out<MemberName> nameOut)
35	            throws InvalidPoolException {
36	        if (request.memberPoolId() != null) {
37	            Pool member = pools.findByIdAndSheetId(request.memberPoolId(), pool.getSheetId())
38	                    .orElseThrow(() -> new InvalidPoolException("There is no such pool on the sheet."));
39	            if (member.getId().equals(pool.getId())) {
40	                throw new InvalidPoolException("A pool cannot be a member of itself.");
41	            }
42	            if (members.findByMemberPoolId(member.getId()).isPresent()) {
43	                throw new InvalidPoolException("That pool is already a member of a pool.");
44	            }
45	            // Walk up from the pool: reaching the member would make it contain itself.
46	            int above = 1;
47	            for (Optional<PoolMember> up = members.findByMemberPoolId(pool.getId()); up.isPresent();
48	                    up = members.findByMemberPoolId(up.get().getPoolId())) {
49	                if (up.get().getPoolId().equals(member.getId())) {
50	                    throw new InvalidPoolException("A pool cannot contain itself.");
51	                }
52	                above++;
53	            }
54	            if (above + height(member.getId(), members) > MAX_DEPTH) {
55	                throw new InvalidPoolException("A chain of pools is at most three deep.");
56	            }
57	            nameOut.set(new MemberName(member.getName()));
58	            memberOut.set(members.saveAndFlush(PoolMember.ofPool(pool.getId(), member.getId(), request.share())
59	                    .during(request.from(), request.to())));
60	            return;
61	        }
62	        Person person = people.findByIdAndSheetId(request.personId(), pool.getSheetId())
63	                .orElseThrow(() -> new InvalidPoolException("There is no such person on the sheet."));
64	        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
65	            throw new InvalidPoolException("That person is already in the pool.");
66	        }
67	        nameOut.set(new MemberName(person.getName()));
68	        memberOut.set(members.saveAndFlush(new PoolMember(pool.getId(), person.getId(), request.share())
69	                .during(request.from(), request.to())));
70	    }
71	
72	    /** How many levels of pools the pool heads: 1 for itself, plus its deepest member pool's. */
73	    private static int height(Long poolId, PoolMemberRepository members) {
74	        int deepest = 0;
75	        for (PoolMember m : members.findByPoolIdOrderByIdAsc(poolId)) {
76	            if (m.getMemberPoolId() != null) deepest = Math.max(deepest, height(m.getMemberPoolId(), members));
77	        }
78	        return 1 + deepest;
79	    }
80	
