411	
412	    public void respond(@Val Sheet current, @RequestParam(name = "asOf", required = false) String asOfParam, AsOf asOf,
413	            PoolRepository pools, PoolMemberRepository members, ObjectResponse<List<PoolResponse>> response)
414	            throws InvalidTodayException {
415	        LocalDate date = AsOf.dateOf(asOfParam);
416	        Sheet sheet = asOf.sheet(current, date);
417	        Map<Long, Person> byId = asOf.people(current.getId(), date).stream()
418	                .collect(Collectors.toMap(Person::getId, Function.identity()));
419	        List<Pool> sheetPools = pools.findBySheetIdOrderByIdAsc(sheet.getId());
420	        Map<Long, Pool> poolsById = sheetPools.stream().collect(Collectors.toMap(Pool::getId, Function.identity()));
421	        Map<Long, List<PoolMember>> membersOf = new HashMap<>();
422	        Set<Long> inAPool = new HashSet<>();
423	        for (Pool pool : sheetPools) {
424	            List<PoolMember> list = members.findByPoolIdOrderByIdAsc(pool.getId());
425	            membersOf.put(pool.getId(), list);
426	            list.forEach(m -> { if (m.getMemberPoolId() != null) inAPool.add(m.getMemberPoolId()); });
427	        }
428	        // Pots flow down from the pools that are members of none.
429	        Map<Long, PoolResponse> shownById = new HashMap<>();
430	        Deque<Map.Entry<Long, BigDecimal>> todo = new ArrayDeque<>();
431	        for (Pool pool : sheetPools) {
432	            if (!inAPool.contains(pool.getId())) todo.add(new SimpleEntry<>(pool.getId(), sheet.getPot()));
433	        }
434	        while (!todo.isEmpty()) {
435	            Map.Entry<Long, BigDecimal> next = todo.poll();
436	            Pool pool = poolsById.get(next.getKey());
437	            if (pool == null || shownById.containsKey(pool.getId())) continue;
438	            BigDecimal total = BigDecimal.ZERO.setScale(2);
439	            List<PoolMember> kept = new ArrayList<>();
440	            List<String> names = new ArrayList<>();
441	            List<BigDecimal> counted = new ArrayList<>();
442	            List<Boolean> held = new ArrayList<>();
443	            List<Boolean> dated = new ArrayList<>();
444	            List<Boolean> retired = new ArrayList<>();
445	            for (PoolMember member : membersOf.get(pool.getId())) {
446	                BigDecimal share;
447	                if (member.getMemberPoolId() != null) {
448	                    Pool sub = poolsById.get(member.getMemberPoolId());
449	                    if (sub == null) continue;
450	                    names.add(sub.getName());
451	                    share = member.getShare();
452	                    held.add(false);
453	                    retired.add(false);
454	                } else {
455	                    Person person = byId.get(member.getPersonId());
456	                    if (person == null) continue;
457	                    names.add(person.getName());
458	                    share = member.getShare();
459	                    boolean isRetired = person.getRetiredFrom() != null;
460	                    held.add(isRetired || (sheet.getToday() != null && person.heldOn(sheet.getToday())));
461	                    retired.add(isRetired);
462	                }
463	                boolean in = member.includes(sheet.getToday());
464	                dated.add(in);
465	                if (in) {
466	                    total = total.add(share);
467	                    counted.add(share);
468	                }
469	                kept.add(member);
470	            }
471	            boolean balanced = total.compareTo(HUNDRED) == 0;
472	            List<Boolean> heldIn = new ArrayList<>();
473	            boolean allRetired = true;
474	            for (int i = 0; i < kept.size(); i++) {
475	                if (!dated.get(i)) continue;
476	                heldIn.add(held.get(i));
477	                if (!retired.get(i)) allRetired = false;
478	            }
479	            List<String> countedCuts = cuts(balanced && !allRetired ? next.getValue() : null, counted, heldIn);
480	            List<String> cuts = new ArrayList<>();
481	            for (int i = 0, j = 0; i < kept.size(); i++) cuts.add(dated.get(i) ? countedCuts.get(j++) : "");
482	            List<PoolResponse.Member> shown = new ArrayList<>();
483	            for (int i = 0; i < kept.size(); i++) {
484	                PoolMember m = kept.get(i);
485	                shown.add(new PoolResponse.Member(m.getPersonId(), m.getMemberPoolId(), names.get(i),
486	                        m.getShare().setScale(2).toPlainString(), cuts.get(i)));
487	                if (m.getMemberPoolId() != null) {
488	                    todo.add(new SimpleEntry<>(m.getMemberPoolId(), cuts.get(i).isEmpty() ? null : new BigDecimal(cuts.get(i))));
489	                }
490	            }
491	            shownById.put(pool.getId(), new PoolResponse(pool.getId(), pool.getName(), total.toPlainString(), balanced, shown));
492	        }
493	        List<PoolResponse> out = new ArrayList<>();
494	        for (Pool pool : sheetPools) {
495	            if (shownById.containsKey(pool.getId())) out.add(shownById.get(pool.getId()));
496	        }
497	        response.send(out);
498	    }
499	
500	    /** Each member's cut of the pot by their counted share out of the counted shares of those not held, in order: ""
501	     *  for all when there is no pot (or the pool is not balanced); 0.00 for a held member. The remainder goes to the
502	     *  smallest non-zero cut, the latest on a tie; with no non-zero cut, to the last not held with a share. */
503	    private static List<String> cuts(BigDecimal pot, List<BigDecimal> shares, List<Boolean> held) {
504	        List<String> out = new ArrayList<>();
505	        if (pot == null) {
506	            shares.forEach(s -> out.add(""));
507	            return out;
508	        }
509	        BigDecimal withCut = BigDecimal.ZERO.setScale(2);
510	        for (int i = 0; i < shares.size(); i++) {
511	            if (!held.get(i)) withCut = withCut.add(shares.get(i));
512	        }
513	        List<BigDecimal> cuts = new ArrayList<>();
514	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
515	        int smallest = -1;
516	        int lastShared = -1;
517	        for (int i = 0; i < shares.size(); i++) {
518	            if (held.get(i) || withCut.signum() == 0) {
519	                cuts.add(BigDecimal.ZERO.setScale(2));
520	                continue;
521	            }
522	            BigDecimal cut = pot.multiply(shares.get(i)).divide(withCut, 2, RoundingMode.HALF_EVEN);
523	            cuts.add(cut);
524	            sum = sum.add(cut);
525	            if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) smallest = i;
526	            if (shares.get(i).signum() != 0) lastShared = i;
527	        }
528	        int to = smallest >= 0 ? smallest : lastShared;
529	        if (to >= 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
530	        cuts.forEach(c -> out.add(c.setScale(2).toPlainString()));
531	        return out;
532	    }
533	}
